import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"复数噪声源","description":"","frontmatter":{},"headers":[],"relativePath":"v0.1.0-alpha/modules/complex_noise_source/index.md","filePath":"v0.1.0-alpha/modules/complex_noise_source/index.md"}'),r={name:"v0.1.0-alpha/modules/complex_noise_source/index.md"};function c(i,t,l,h,n,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="复数噪声源" tabindex="-1">复数噪声源 <a class="header-anchor" href="#复数噪声源" aria-label="Permalink to &quot;复数噪声源&quot;">​</a></h1><p>适用：v0.1.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>complex_noise_source</code> · 模块定义版本：2</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>生成复数随机噪声，用于在 I/Q 平面模拟随机扰动。它可与复数载波或星座输出相加，观察噪声对幅度、相位与判决的影响。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>复数信号源.out → 复数加法器.in1</code>，<code>复数噪声源.out → 复数加法器.in2</code>。源采样率相同后，再分别观察加噪前后 I/Q 或星座分布。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>幅度调节随机扰动尺度，分布改变 I/Q 样本的统计形状。复数噪声的尺度不能直接套用到实数噪声的单分量统计，更不能直接填入某个期望 SNR。</p><p>固定种子用于重复起始条件，系统时间种子用于重新生成序列。比较噪声效果时固定信号幅度、观察长度与显示范围，先只改变一项设置。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>采样率 (Hz)<br><code>sample_rate_hz</code></td><td><code>4096</code></td><td>范围 1 至 1000000；Master 支持 1–1000000 Hz，可输入小数；下限保证单个采样周期不超过 1 秒。</td><td>重新准备</td></tr><tr><td>噪声幅度<br><code>amplitude</code></td><td><code>0</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>噪声分布<br><code>distribution</code></td><td><code>gaussian</code></td><td>高斯 (<code>gaussian</code>)；均匀 (<code>uniform</code>)</td><td>可在线应用</td></tr><tr><td>种子模式<br><code>seed_mode</code></td><td><code>fixed</code></td><td>固定 (<code>fixed</code>)；系统时间 (<code>system_time</code>)</td><td>重新准备</td></tr><tr><td>固定种子<br><code>seed</code></td><td><code>0</code></td><td>范围 0 至 2147483646</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>amplitude</code></li><li><code>distribution</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>在线修改后继续产生新的复数随机样本，不会重新计算已经收到的星座点。切换种子模式或重新从种子开始时，停止并重新准备；不能用隐藏窗口的方式重启随机状态。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><p>复数处理示例把噪声加入两个复数相量的和。观察复数加法器的 I/Q 轨迹，再单独绑定复数噪声源输出查看随机散布。示例是软件噪声，不是接收机采集。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>星座散布变大一定代表 SNR 下降多少 dB？</strong> 还需依据实际信号功率、噪声功率和带宽测量，幅度参数本身不给出这个比值。</p><p><strong>固定种子后窗口里的点还在变化？</strong> 同一次运行仍在向前生成样本；重复性要比较重新准备后的对应序列位置。</p>',28)])])}const m=e(r,[["render",c]]);export{u as __pageData,m as default};
